# Analysis
def analyze_demo(idx):
    inp = demos[idx]['input']
    out = demos[idx]['output']

    h, w = len(inp), len(inp[0])

    # Find all changes
    changes = []
    unchanged_9s = []
    for i in range(h):
        for j in range(w):
            if inp[i][j] != out[i][j]:
                changes.append((i, j, inp[i][j]))
            elif inp[i][j] == 9 and out[i][j] == 9:
                unchanged_9s.append((i, j))

    print(f"\n=== Demo {idx} ===")
    print(f"Changes: {len(changes)}, 9s unchanged: {len(unchanged_9s)}")
    if unchanged_9s:
        print(f"Unchanged 9s: {unchanged_9s}")

    # Check uniform rows
    uniform_rows = []
    for i in range(h):
        if len(set(inp[i])) == 1:
            uniform_rows.append((i, inp[i][0]))

    # Check uniform cols
    uniform_cols = []
    for j in range(w):
        col = [inp[i][j] for i in range(h)]
        if len(set(col)) == 1:
            uniform_cols.append((j, col[0]))

    print(f"Uniform rows: {uniform_rows}")
    print(f"Uniform cols: {uniform_cols}")

    # For cells that SHOULD be 2 (in uniform row or col), check
    should_be_2 = []
    for i in range(h):
        for j in range(w):
            if inp[i][j] == 9:
                if (i, inp[i][0]) in uniform_rows or (j, inp[i][j]) in uniform_cols:
                    should_be_2.append((i, j, inp[i][j]))

    correct_changes = [p for p in should_be_2 if (p[0], p[1]) not in unchanged_9s]
    stayed_9 = [p for p in should_be_2 if p in unchanged_9s]

    print(f"Cells in uniform row/col that became 2: {len(correct_changes)}")
    if stayed_9:
        print(f"Cells in uniform row/col that stayed 9: {stayed_9}")

